def compute(vars):
    try:
        thereafter = vars["v1"]
        total = vars["v2"]
        portion = thereafter / total
    except ZeroDivisionError:
        return None

    return {
        "value": portion,
        "trace": {
            "thereafter": thereafter,
            "total": total,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": "ratio",
                "unit": "ratio"
            }
        }
    }
